<?php
namespace Tests\Feature;use App\Jobs\RenderVideoClipJob;use App\Models\User;use App\Models\Video;use App\Models\VideoClip;use App\Services\VideoClipRenderer;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Queue;use Tests\TestCase;
class VideoClipTest extends TestCase{use RefreshDatabase;
 public function test_clip_dimensions_queue_and_public_review_gate():void{$this->assertSame([1080,1920],app(VideoClipRenderer::class)->dimensions('9:16'));$this->assertSame([1080,1080],app(VideoClipRenderer::class)->dimensions('1:1'));$user=User::factory()->create();$video=Video::create(['title'=>'Original','slug'=>'original','provider'=>'file','video_path'=>'videos/original.mp4','is_published'=>true]);$clip=VideoClip::create(['video_id'=>$video->id,'title'=>'Recorte','status'=>'queued','aspect_ratio'=>'9:16','starts_at_ms'=>0,'ends_at_ms'=>30000,'requested_by'=>$user->id]);Queue::fake();RenderVideoClipJob::dispatch($clip->id);Queue::assertPushed(RenderVideoClipJob::class);$this->get(route('video-clips.show',$clip))->assertNotFound();$clip->update(['status'=>'approved','output_path'=>'shorts/final.mp4']);$this->get(route('video-clips.show',$clip))->assertRedirect();}
}
